import{_ as o,o as t,c as r,a2 as a}from"./chunks/framework.CyZTVJbV.js";const p=JSON.parse('{"title":"OAuth 2.1 Provider Dogfood — pkce-flow quality report","description":"","frontmatter":{},"headers":[],"relativePath":"quality-reports/auth/oauth21-provider-pkce.md","filePath":"quality-reports/auth/oauth21-provider-pkce.md"}'),d={name:"quality-reports/auth/oauth21-provider-pkce.md"};function i(c,e,s,n,l,h){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="oauth-2-1-provider-dogfood-—-pkce-flow-quality-report" tabindex="-1">OAuth 2.1 Provider Dogfood — pkce-flow quality report <a class="header-anchor" href="#oauth-2-1-provider-dogfood-—-pkce-flow-quality-report" aria-label="Permalink to &quot;OAuth 2.1 Provider Dogfood — pkce-flow quality report&quot;">​</a></h1><p>PKCE report for <code>examples/dogfood-oauth21-provider</code> Sub-Issue #865 (v1.21-3b).</p><p>Extends the endpoints-skeleton report (Sub-Issue #864 → <code>oauth21-provider-endpoints.md</code>) with PKCE-specific behavioural fidelity. The mock adapter (<code>@kiwa-test/auth</code>&#39;s <code>setupOAuth21Env</code> + <code>createAuthorizationServer</code>) covers every axis unconditionally; the real adapter (<code>oauth2-mock-server</code> via testcontainers) is env-skipped through <code>KIWA_OAUTH21_ENV_MISSING</code> until Sub-Issue #866 / #867 ships the container image + wiring, so the real column shows the assertion contract rather than a green run.</p><h2 id="fidelity-axes-pkce-flow" tabindex="-1">Fidelity axes (pkce-flow) <a class="header-anchor" href="#fidelity-axes-pkce-flow" aria-label="Permalink to &quot;Fidelity axes (pkce-flow)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>axis</th><th>RFC anchor</th><th>mock (<code>@kiwa-test/auth</code>)</th><th>real (oauth2-mock-server, gated by <code>OAUTH21_BOOTSTRAP=1</code>)</th><th>assertion</th></tr></thead><tbody><tr><td>1. verifier entropy</td><td>RFC 7636 §4.1</td><td><code>createPkceChallenge</code> (kiwa) → 43-char base64url string from the unreserved URL set <code>[A-Za-z0-9-._~]</code>; <code>assertVerifierFormat</code> refuses length &lt; 43, length &gt; 128, or reserved chars with <code>verifier_too_short</code> / <code>verifier_too_long</code> / <code>verifier_invalid_charset</code></td><td>oauth2-mock-server accepts any 43-128 char verifier the client sends and rejects malformed input at the <code>/token</code> layer with <code>invalid_request</code>; identical char-set restriction</td><td>Both drivers reject any verifier outside the RFC 7636 §4.1 shape before a token is minted. Format failures are pre-flight (<code>invalid_request</code>), distinct from cryptographic mismatch (<code>invalid_grant</code>).</td></tr><tr><td>2. challenge derivation</td><td>RFC 7636 §4.2</td><td><code>deriveChallengeS256(verifier)</code> returns <code>base64url(SHA-256(verifier))</code> — 43 chars, no padding, no <code>+</code> or <code>/</code>. Hand-computed via <code>node:crypto</code> and cross-checked with the kiwa helper</td><td>oauth2-mock-server re-computes the challenge server-side using the same SHA-256 + base64url encoder</td><td>Cross-driver assertion: the derived challenge must match byte-for-byte the challenge stored at <code>/authorize</code>. Padding, <code>+</code>, <code>/</code> or a shorter length signals a downgrade.</td></tr><tr><td>3. S256 method enforcement</td><td>RFC 9700 §2.1.1</td><td><code>assertMethodAllowed</code> refuses <code>plain</code> with <code>method_plain_refused</code>, unknown methods with <code>method_unknown_refused</code>, missing method with <code>method_missing_refused</code>. The Hono <code>/authorize</code> route runs the guard before the adapter is invoked so the error kind is identical across mock + real</td><td>oauth2-mock-server refuses <code>plain</code> + unknown methods with <code>invalid_request</code> at the HTTP layer; discovery advertises <code>code_challenge_methods_supported=[S256]</code> only</td><td>Both drivers refuse every downgrade path at <code>/authorize</code> (missing method / <code>plain</code> / unknown method / missing challenge) before a code is minted. Client cannot fall back to <code>plain</code> even by omitting the parameter.</td></tr><tr><td>4. verifier mismatch rejection</td><td>RFC 6749 §5.2 + RFC 7636 §4.6</td><td>Mock AS re-derives the challenge from the submitted verifier and diffs against the recorded challenge — mismatch surfaces as <code>invalid_grant</code>. <code>assertVerifierMatches</code> provides the same guard for callers that drive the AS without HTTP</td><td>oauth2-mock-server does the same server-side check and returns <code>invalid_grant</code> on mismatch</td><td>Cross-driver invariant: swapping the verifier from a sibling challenge always produces <code>invalid_grant</code> (not <code>invalid_request</code>). The kind distinction lets the client tell &quot;I broke the format&quot; from &quot;someone else forged the exchange&quot;.</td></tr></tbody></table><h2 id="pkce-guard-implementation-notes" tabindex="-1">PKCE guard implementation notes <a class="header-anchor" href="#pkce-guard-implementation-notes" aria-label="Permalink to &quot;PKCE guard implementation notes&quot;">​</a></h2><ul><li><code>src/lib/pkce.ts</code> re-exports the kiwa primitives (<code>createPkceChallenge</code>, <code>deriveCodeChallenge</code>, <code>verifyCodeChallenge</code>) so the dogfood app never imports directly from <code>@kiwa-test/auth</code> in the app layer. Downstream Sub-Issues can swap the kiwa helper for a different implementation without touching the route handlers.</li><li><code>PkceValidationError.kind</code> is the SSOT for the OAuth 2.1 error code mapping. <code>mapPkceKindToAuthorizeCode</code> / <code>mapPkceKindToTokenCode</code> in <code>src/lib/hono-app.ts</code> translate a rejection kind to <code>invalid_request</code> (pre-flight failure) or <code>invalid_grant</code> (cryptographic mismatch). Both maps are exhaustive over the kind union so the type checker catches missing branches when a new kind is added.</li><li><code>assertAuthorizePkce</code> runs before <code>adapter.authorize(...)</code> so mock + real see the same rejection surface for downgrade attempts. The Hono handler still forwards the request to the adapter after the guard succeeds — the AS re-checks internally (defence in depth).</li><li><code>assertTokenPkce</code> runs before <code>adapter.token(...)</code> for <code>authorization_code</code> requests. <code>refresh_token</code> requests are a no-op (no verifier at that stage). Cryptographic mismatch stays inside the AS because the recorded challenge lives there — the guard is a pre-flight format sanity check.</li></ul><h2 id="real-adapter-scaffolding" tabindex="-1">Real-adapter scaffolding <a class="header-anchor" href="#real-adapter-scaffolding" aria-label="Permalink to &quot;Real-adapter scaffolding&quot;">​</a></h2><ul><li><code>startOAuth2MockServer()</code> in <code>src/adapters/real.ts</code> is the container entry point. Three env states: <ul><li><code>OAUTH21_BOOTSTRAP</code> unset → rejects with <code>KIWA_OAUTH21_ENV_MISSING</code> (matches the endpoints-skeleton env-detect contract).</li><li><code>OAUTH21_BOOTSTRAP=1</code> + <code>OAUTH21_MOCK_SERVER_URL=&lt;url&gt;</code> → returns a handle pointing at a caller-managed server (docker-compose flow). Handle exposes typed endpoint URLs so the pkce-flow harness can point fetch at <code>authorizationEndpoint</code> / <code>tokenEndpoint</code> etc.</li><li><code>OAUTH21_BOOTSTRAP=1</code> without <code>OAUTH21_MOCK_SERVER_URL</code> → rejects with <code>KIWA_OAUTH21_ENV_MISSING</code>. Sub-Issue #866 / #867 replaces this branch with a testcontainers <code>GenericContainer</code> once the workspace commits the <code>testcontainers</code> dependency. The rejection message names the follow-up Sub-Issues explicitly so future contributors do not have to read this report to know where the wiring lives.</li></ul></li><li><code>makeRealAdapter</code> continues to record every failed method call with <code>errorKind=&#39;KIWA_OAUTH21_ENV_MISSING&#39;</code> so the fidelity report captures &quot;environment absent&quot; rather than &quot;assertion failed&quot; (same pattern as <code>examples/dogfood-supabase-saas-app</code>).</li></ul><h2 id="test-coverage" tabindex="-1">Test coverage <a class="header-anchor" href="#test-coverage" aria-label="Permalink to &quot;Test coverage&quot;">​</a></h2><ul><li><code>tests/pkce-flow.spec.ts</code> — 31 tests, split into five describe blocks: <ul><li><code>axis 1 — verifier entropy (RFC 7636 §4.1)</code> — 6 tests covering the 43-128 char band + unreserved charset + rejection kinds + interop with kiwa&#39;s <code>generateCodeVerifier</code>.</li><li><code>axis 2 — challenge derivation (RFC 7636 §4.2)</code> — 4 tests covering hand-computed SHA-256 → base64url match + kiwa cross-check + verify pair match + mismatch.</li><li><code>axis 3 — S256 method enforcement (RFC 9700 §2.1.1)</code> — 7 tests covering <code>PKCE_ALLOWED_METHOD</code> constant + <code>plain</code> / unknown / missing method rejections + <code>/authorize</code> HTTP rejections (<code>plain</code> / no method / no challenge) + happy path.</li><li><code>axis 4 — verifier mismatch rejection (RFC 6749 §5.2)</code> — 8 tests covering <code>assertVerifierMatches</code> (match + mismatch) + <code>/token</code> HTTP rejections (mismatch → <code>invalid_grant</code>, malformed → <code>invalid_request</code>) + happy path + <code>assertTokenPkce</code> guard behaviour.</li><li><code>real adapter — env-skip + startOAuth2MockServer scaffolding</code> — 6 tests validating the <code>KIWA_OAUTH21_ENV_MISSING</code> gate + <code>OAUTH21_MOCK_SERVER_URL</code> handle shape + trailing slash normalisation + trace bookkeeping.</li></ul></li></ul><p>Total: 46 tests across the endpoints-skeleton (15) + pkce-flow (31) specs. All passing on the mock adapter; real assertions gated by <code>OAUTH21_BOOTSTRAP=1</code>.</p><h2 id="environment-gating" tabindex="-1">Environment gating <a class="header-anchor" href="#environment-gating" aria-label="Permalink to &quot;Environment gating&quot;">​</a></h2><ul><li><code>KIWA_MODE=mock</code> — forces the mock adapter; every axis runs unconditionally.</li><li><code>OAUTH21_BOOTSTRAP=1</code> — opt-in for real ceremonies. Combined with <code>OAUTH21_MOCK_SERVER_URL=&lt;url&gt;</code> the harness can drive an externally-managed oauth2-mock-server (docker-compose flow).</li><li>Without <code>OAUTH21_BOOTSTRAP=1</code>, the real adapter&#39;s <code>discovery()</code> still returns a valid metadata document (static shape derived from <code>issuer</code>); every other method reports <code>KIWA_OAUTH21_ENV_MISSING</code>.</li></ul><h2 id="known-follow-ups" tabindex="-1">Known follow-ups <a class="header-anchor" href="#known-follow-ups" aria-label="Permalink to &quot;Known follow-ups&quot;">​</a></h2><ul><li>Sub-Issue #866 (<code>dpop-refresh-rotation</code>) — DPoP proof binding at <code>/token</code> + refresh token rotation with re-use detection; the pkce-flow harness will layer DPoP proof presence checks on top of the axis-3 assertions.</li><li>Sub-Issue #867 (<code>revocation-fidelity-release-gate</code>) — Revocation cascade (revoke access → refresh family torn down) + real vs mock fidelity harness (5 endpoints × 4-6 axes = 24 axis grid) + release gate 7-axis integrated report + testcontainers dependency commit.</li></ul>',16)])])}const m=o(d,[["render",i]]);export{p as __pageData,m as default};
